Suggested fix: do not use the shortcut when `hasBlocks()` is true. The queries then use the regular skipper range iterator, which skips the intervals whose minimum and maximum do not intersect the range and checks the values of the others, without assuming a contiguous docID range. It makes the same invalid assumption as #16886, in a different query.

#### Reproduction

Save as `DenseShortcutRepro.java` and run `java -cp <lucene-core jar> DenseShortcutRepro.java`. It checks `SortedNumericDocValuesRangeQuery` and `SortedSetDocValuesRangeQuery`. Each query on the sort field is checked against the expected ids, and against the same range on a copy of the field that has no skipper and is not the sort field, so it cannot use the shortcut. It throws an `AssertionError` that lists the failing queries on the versions below.

```java
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.TreeSet;
import org.apache.lucene.document.Document;
import org.apache.lucene.document.StoredField;
import org.apache.lucene.document.SortedNumericDocValuesField;
import org.apache.lucene.document.SortedSetDocValuesField;
import org.apache.lucene.index.DirectoryReader;
import org.apache.lucene.index.IndexWriter;
import org.apache.lucene.index.IndexWriterConfig;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.Query;
import org.apache.lucene.search.ScoreDoc;
import org.apache.lucene.search.Sort;
import org.apache.lucene.search.SortField;
import org.apache.lucene.search.SortedNumericSortField;
import org.apache.lucene.search.SortedSetSortField;
import org.apache.lucene.store.ByteBuffersDirectory;
import org.apache.lucene.store.Directory;
import org.apache.lucene.util.BytesRef;

public class DenseShortcutRepro {

  static final String EXPECTED = "ids=[1, 2, 3] count=3";

  public static void main(String[] args) throws Exception {
    List<String> failures = new ArrayList<>();
    failures.add(check(false));
    failures.add(check(true));
    failures.removeIf(Objects::isNull);
    if (failures.isEmpty() == false) {
      throw new AssertionError(failures);
    }
  }

  static String check(boolean sortedSet) throws IOException {
    try (Directory dir = new ByteBuffersDirectory();
        IndexWriter writer = new IndexWriter(dir, indexWriterConfig(sortedSet))) {
      addBlock(writer, sortedSet, 0, 2, 1);
      addBlock(writer, sortedSet, 2, 0, 0);
      try (DirectoryReader reader = DirectoryReader.open(writer)) {
        IndexSearcher searcher = new IndexSearcher(reader);
        String reference = result(searcher, rangeQuery("g", sortedSet));
        String actual = result(searcher, rangeQuery("f", sortedSet));
        if (EXPECTED.equals(actual) && EXPECTED.equals(reference)) {
          return null;
        }
        String type = sortedSet ? "sorted set" : "sorted numeric";
        return type + ": expected " + EXPECTED + " but got " + actual
            + " (reference field: " + reference + ")";
      }
    }
  }

  static String result(IndexSearcher searcher, Query query) throws IOException {
    Set<Integer> ids = new TreeSet<>();
    for (ScoreDoc hit : searcher.search(query, 10).scoreDocs) {
      ids.add(searcher.storedFields().document(hit.doc).getField("id").numericValue().intValue());
    }
    return "ids=" + ids + " count=" + searcher.count(query);
  }

  static IndexWriterConfig indexWriterConfig(boolean sortedSet) {
    SortField sortField =
        sortedSet
            ? new SortedSetSortField("f", false)
            : new SortedNumericSortField("f", SortField.Type.LONG, false);
    return new IndexWriterConfig().setIndexSort(new Sort(sortField)).setParentField("parent");
  }

  static void addBlock(IndexWriter writer, boolean sortedSet, int id, int child, int parent)
      throws IOException {
    writer.addDocuments(
        List.of(document(sortedSet, id, child), document(sortedSet, id + 1, parent)));
  }

  static Document document(boolean sortedSet, int id, int value) {
    Document document = new Document();
    document.add(new StoredField("id", id));
    if (sortedSet) {
      document.add(SortedSetDocValuesField.indexedField("f", new BytesRef("t" + value)));
      document.add(new SortedSetDocValuesField("g", new BytesRef("t" + value)));
    } else {
      document.add(SortedNumericDocValuesField.indexedField("f", value));
      document.add(new SortedNumericDocValuesField("g", value));
    }
    return document;
  }

  static Query rangeQuery(String field, boolean sortedSet) {
    if (sortedSet) {
      return SortedSetDocValuesField.newSlowRangeQuery(
          field, new BytesRef("t0"), new BytesRef("t1"), true, true);
    }
    return SortedNumericDocValuesField.newSlowRangeQuery(field, 0, 1);
  }
}
```

