### Description

`IndexSortSortedNumericDocValuesRangeQuery` can return wrong hits, wrong counts, or throw an `IllegalArgumentException` on segments with document blocks (`LeafMetaData#hasBlocks()`).

With a parent field, blocks are sorted by the sort key of their parent. The documents inside a block are not ordered by their own values: a child either has no value (it reads as the missing value) or an unrelated one. The query assumes the values follow the docID order in two places, the binary search over the doc values and the docID range it derives from the points.

Ascending `LONG` sort, three blocks `[child, parent]` with parent values 10, 20 and 30, and no value on the children. The values by docID are `[missing, 10, missing, 20, missing, 30]`. For the range `[20, 20]` the query returns no hit instead of one. With points the hit is right but `IndexSearcher#count` returns 0.

With values on the children and points, take the blocks `[child 2, parent 1]` and `[child 0, parent 0]`. The range `[0, 0]` returns 3 hits instead of 2, and `[1, 1]` throws `IllegalArgumentException: minDoc must be < maxDoc`.

Segments without blocks are fine.

Suggested fix: when `hasBlocks()` is true, skip both shortcuts in the scorer and in `count()` and use the fallback query. This assumes the fallback is correct, which is not the case for a dense field with a doc values skipper, see #16885.

#### Reproduction

Save as `BlocksRepro.java` and run `java -cp <lucene-core jar> BlocksRepro.java`. Each case checks the expected number of matches and compares the query with its fallback query alone, which is correct here. It throws an `AssertionError` that lists the four failing cases on the versions below.

```java
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import org.apache.lucene.document.Document;
import org.apache.lucene.document.LongPoint;
import org.apache.lucene.document.SortedNumericDocValuesField;
import org.apache.lucene.index.DirectoryReader;
import org.apache.lucene.index.IndexWriter;
import org.apache.lucene.index.IndexWriterConfig;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.IndexSortSortedNumericDocValuesRangeQuery;
import org.apache.lucene.search.Query;
import org.apache.lucene.search.Sort;
import org.apache.lucene.search.SortField;
import org.apache.lucene.search.SortedNumericSelector;
import org.apache.lucene.search.SortedNumericSortField;
import org.apache.lucene.store.ByteBuffersDirectory;
import org.apache.lucene.store.Directory;

public class BlocksRepro {

  static final long NO_VALUE = -1;
  static final long[][] CHILDREN_WITHOUT_VALUES = {{NO_VALUE, 10}, {NO_VALUE, 20}, {NO_VALUE, 30}};
  static final long[][] CHILDREN_WITH_VALUES = {{2, 1}, {0, 0}};

  public static void main(String[] args) throws Exception {
    List<String> failures = new ArrayList<>();
    failures.add(check("children without values", CHILDREN_WITHOUT_VALUES, false, 20, 1));
    failures.add(check("children without values", CHILDREN_WITHOUT_VALUES, true, 20, 1));
    failures.add(check("children with values", CHILDREN_WITH_VALUES, true, 0, 2));
    failures.add(check("children with values", CHILDREN_WITH_VALUES, true, 1, 1));
    failures.removeIf(Objects::isNull);
    if (failures.isEmpty() == false) {
      throw new AssertionError(failures);
    }
  }

  static String check(String name, long[][] blocks, boolean points, long value, int matches)
      throws IOException {
    String description = name + ", points=" + points + ", range [" + value + ", " + value + "]: ";
    try (Directory dir = new ByteBuffersDirectory();
        IndexWriter writer = new IndexWriter(dir, indexWriterConfig())) {
      for (long[] block : blocks) {
        addBlock(writer, block[0], block[1], points);
      }
      try (DirectoryReader reader = DirectoryReader.open(writer)) {
        return compare(new IndexSearcher(reader), value, matches, description);
      }
    } catch (IllegalArgumentException e) {
      if (String.valueOf(e.getMessage()).contains("minDoc must be < maxDoc") == false) {
        throw e;
      }
      return description + e;
    }
  }

  static String compare(IndexSearcher searcher, long value, int matches, String description)
      throws IOException {
    Query reference = SortedNumericDocValuesField.newSlowRangeQuery("ts", value, value);
    Query query = new IndexSortSortedNumericDocValuesRangeQuery("ts", value, value, reference);
    String expected = "hits=" + matches + " count=" + matches;
    String referenceResult = result(searcher, reference);
    String actual = result(searcher, query);
    if (expected.equals(actual) && expected.equals(referenceResult)) {
      return null;
    }
    return description + "expected " + expected + " but got " + actual
        + " (reference " + referenceResult + ")";
  }

  static String result(IndexSearcher searcher, Query query) throws IOException {
    long hits = searcher.search(query, 10).totalHits.value();
    return "hits=" + hits + " count=" + searcher.count(query);
  }

  static IndexWriterConfig indexWriterConfig() {
    SortField sortField =
        new SortedNumericSortField(
            "ts", SortField.Type.LONG, false, SortedNumericSelector.Type.MIN, Long.MAX_VALUE);
    return new IndexWriterConfig().setIndexSort(new Sort(sortField)).setParentField("parent");
  }

  static void addBlock(IndexWriter writer, long child, long parent, boolean points)
      throws IOException {
    writer.addDocuments(List.of(document(child, points), document(parent, points)));
  }

  static Document document(long value, boolean points) {
    Document document = new Document();
    if (value != NO_VALUE) {
      document.add(new SortedNumericDocValuesField("ts", value));
      if (points) {
        document.add(new LongPoint("ts", value));
      }
    }
    return document;
  }
}
```

### Version and environment details

Lucene 10.4.0, 10.5.2, a 10.6.0 snapshot and `main` at `bc0d7097dc`. Java 25.

