            execute(connection, "SELECT COUNT(*) FROM T_PLAIN WHERE ID = 6801 AND CURRENT_DATE > DATE '2000-01-01'");
            // Firebird server: "INSERT INTO T_TS (ID, TS) VALUES (6802, TIMESTAMP '2026-10-15 10:11:12.3456') -> update count 1";
            // proxy: "INSERT INTO T_TS (ID, TS) VALUES (6802, TIMESTAMP '2026-10-15 10:11:12.3456') -> error: Unknown exception. More details: java.lang.IllegalStateException: Literals must have string, number, dateTime, hex, bit, boolean or null. [SQLState:HY000, ISC error code:335544382]"
