            // proxy: "SELECT 1 FROM RDB$DATABASE WHERE NEXT VALUE FOR S_AUDIT_SEQ > 0 -> error: Dynamic SQL Error; You have an error in your SQL syntax: no viable alternative at input 'NEXT' [SQLState:42000, ISC error code:335544569]"
            execute(connection, "SELECT 1 FROM RDB$DATABASE WHERE NEXT VALUE FOR S_AUDIT_SEQ > 0");
            // Firebird server: "SELECT ID FROM T_PLAIN WHERE NAME CONTAINING 'x' AND ID = -1 -> ID INTEGER: no rows";
            // proxy: "SELECT ID FROM T_PLAIN WHERE NAME CONTAINING 'x' AND ID = -1 -> error: Dynamic SQL Error; You have an error in your SQL syntax: no viable alternative at input 'NAMECONTAINING' [SQLState:42000, ISC error code:335544569]"
            execute(connection, "SELECT ID FROM T_PLAIN WHERE NAME CONTAINING 'x' AND ID = -1");
            // Firebird server: "SELECT ID FROM T_PLAIN WHERE SINGULAR (SELECT 1 FROM RDB$DATABASE) AND ID = -1 -> ID INTEGER: no rows";
            // proxy: "SELECT ID FROM T_PLAIN WHERE SINGULAR (SELECT 1 FROM RDB$DATABASE) AND ID = -1 -> error: Dynamic SQL Error; You have an error in your SQL syntax: no viable alternative at input 'SINGULAR(SELECT' [SQLState:42000, ISC error code:335544569]"
            execute(connection, "SELECT ID FROM T_PLAIN WHERE SINGULAR (SELECT 1 FROM RDB$DATABASE) AND ID = -1");
        }
    }

    // Executes the statement and prints the described columns with the rows, the update count or the error
    static void execute(final Connection connection, final String sql) {
        try (Statement statement = connection.createStatement()) {
            if (!statement.execute(sql)) {
                System.out.println(sql + " -> update count " + statement.getUpdateCount());
                return;
            }
            try (ResultSet resultSet = statement.getResultSet()) {
                ResultSetMetaData metaData = resultSet.getMetaData();
                List<String> columns = new ArrayList<>();
                for (int i = 1; i <= metaData.getColumnCount(); i++) {
                    int type = metaData.getColumnType(i);
                    boolean text = Types.CHAR == type || Types.VARCHAR == type;
                    columns.add(metaData.getColumnLabel(i) + " " + metaData.getColumnTypeName(i) + (text ? "(" + metaData.getPrecision(i) + ")" : ""));
                }
                List<String> rows = new ArrayList<>();
                while (resultSet.next()) {
