import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.sql.Statement;
import java.sql.Types;
import java.util.ArrayList;
import java.util.List;

public class DdlStatements {

    // The proxy; put the URL, user and password of the Firebird server here to compare
    static final String URL = "jdbc:firebirdsql://<proxy host>:<proxy port>/firebird_db?encoding=UTF8&wireCrypt=DISABLED";

    static final String USER = "root";

    static final String PASSWORD = "root";

    public static void main(final String[] args) throws SQLException {
        try (Connection connection = DriverManager.getConnection(URL, USER, PASSWORD)) {
            // Firebird server: "RECREATE TABLE T_AUDIT_RECREATE (ID INTEGER) -> update count -1";
            // proxy: "RECREATE TABLE T_AUDIT_RECREATE (ID INTEGER) -> error: Dynamic SQL Error; You have an error in your SQL syntax: no viable alternative at input 'RECREATE' [SQLState:42000, ISC error code:335544569]"
            execute(connection, "RECREATE TABLE T_AUDIT_RECREATE (ID INTEGER)");
            // Firebird server: "DROP TABLE T_AUDIT_RECREATE -> update count -1";
            // proxy: "DROP TABLE T_AUDIT_RECREATE -> error: Table or view 'T_AUDIT_RECREATE' does not exist. [SQLState:HY000, ISC error code:335544382]"
            execute(connection, "DROP TABLE T_AUDIT_RECREATE");
            // Firebird server: "SET GENERATOR S_AUDIT_SEQ TO 0 -> update count -1";
            // proxy: "SET GENERATOR S_AUDIT_SEQ TO 0 -> error: Dynamic SQL Error; You have an error in your SQL syntax: SET GENERATOR S_AUDIT_SEQ TO 0, null [SQLState:42000, ISC error code:335544569]"
            execute(connection, "SET GENERATOR S_AUDIT_SEQ TO 0");
            // Firebird server: "RECREATE SEQUENCE S_AUDIT_TMP -> update count -1";
            // proxy: "RECREATE SEQUENCE S_AUDIT_TMP -> error: Dynamic SQL Error; You have an error in your SQL syntax: no viable alternative at input 'RECREATE' [SQLState:42000, ISC error code:335544569]"
            execute(connection, "RECREATE SEQUENCE S_AUDIT_TMP");
            // Firebird server: "DROP SEQUENCE S_AUDIT_TMP -> update count -1";
            // proxy: "DROP SEQUENCE S_AUDIT_TMP -> error: Dynamic SQL Error; You have an error in your SQL syntax: no viable alternative at input 'DROPSEQUENCE' [SQLState:42000, ISC error code:335544569]"
            execute(connection, "DROP SEQUENCE S_AUDIT_TMP");
            // Firebird server: "CREATE INDEX I_AUDIT_DDL ON T_PLAIN (NAME) -> update count -1";
            // proxy: "CREATE INDEX I_AUDIT_DDL ON T_PLAIN (NAME) -> error: Dynamic SQL Error; You have an error in your SQL syntax: no viable alternative at input 'CREATEINDEX' [SQLState:42000, ISC error code:335544569]"
            execute(connection, "CREATE INDEX I_AUDIT_DDL ON T_PLAIN (NAME)");
            // Firebird server: "DROP INDEX I_AUDIT_DDL -> update count -1";
            // proxy: "DROP INDEX I_AUDIT_DDL -> error: Dynamic SQL Error; You have an error in your SQL syntax: no viable alternative at input 'DROPINDEX' [SQLState:42000, ISC error code:335544569]"
            execute(connection, "DROP INDEX I_AUDIT_DDL");
            // Firebird server: "RECREATE EXCEPTION E_AUDIT_DDL 'audit' -> update count -1";
            // proxy: "RECREATE EXCEPTION E_AUDIT_DDL 'audit' -> error: Dynamic SQL Error; You have an error in your SQL syntax: no viable alternative at input 'RECREATE' [SQLState:42000, ISC error code:335544569]"
            execute(connection, "RECREATE EXCEPTION E_AUDIT_DDL 'audit'");
            // Firebird server: "DROP EXCEPTION E_AUDIT_DDL -> update count -1";
            // proxy: "DROP EXCEPTION E_AUDIT_DDL -> error: Dynamic SQL Error; You have an error in your SQL syntax: no viable alternative at input 'DROPEXCEPTION' [SQLState:42000, ISC error code:335544569]"
            execute(connection, "DROP EXCEPTION E_AUDIT_DDL");
        }
    }

    // Executes the statement and prints the described columns with the rows, the update count or the error
    static void execute(final Connection connection, final String sql) {
        try (Statement statement = connection.createStatement()) {
            if (!statement.execute(sql)) {
                System.out.println(sql + " -> update count " + statement.getUpdateCount());
                return;
            }
            try (ResultSet resultSet = statement.getResultSet()) {
                ResultSetMetaData metaData = resultSet.getMetaData();
                List<String> columns = new ArrayList<>();
                for (int i = 1; i <= metaData.getColumnCount(); i++) {
                    int type = metaData.getColumnType(i);
                    boolean text = Types.CHAR == type || Types.VARCHAR == type;
                    columns.add(metaData.getColumnLabel(i) + " " + metaData.getColumnTypeName(i) + (text ? "(" + metaData.getPrecision(i) + ")" : ""));
                }
                List<String> rows = new ArrayList<>();
                while (resultSet.next()) {
                    List<String> values = new ArrayList<>();
                    for (int i = 1; i <= metaData.getColumnCount(); i++) {
                        values.add(String.valueOf(resultSet.getObject(i)));
                    }
                    rows.add(String.join(", ", values));
                }
                System.out.println(sql + " -> " + String.join(", ", columns) + ": " + (rows.isEmpty() ? "no rows" : String.join("; ", rows)));
            }
        } catch (final SQLException ex) {
            System.out.println(sql + " -> error: " + ex.getMessage());
        }
    }
}
