            // Firebird server: "SELECT -RDB$RELATION_ID FROM RDB$DATABASE ->  SMALLINT: -N";
            // proxy: "SELECT -RDB$RELATION_ID FROM RDB$DATABASE -> update count 0"
            execute(connection, "SELECT -RDB$RELATION_ID FROM RDB$DATABASE");
            // Firebird server: "SELECT DISTINCT(RDB$RELATION_ID) FROM RDB$DATABASE -> RDB$RELATION_ID SMALLINT: N";
            // proxy: "SELECT DISTINCT(RDB$RELATION_ID) FROM RDB$DATABASE -> update count 0"
            execute(connection, "SELECT DISTINCT(RDB$RELATION_ID) FROM RDB$DATABASE");
            // Firebird server: "SELECT (RDB$RELATION_ID) FROM RDB$DATABASE -> RDB$RELATION_ID SMALLINT: N";
            // proxy: "SELECT (RDB$RELATION_ID) FROM RDB$DATABASE -> update count 0"
            execute(connection, "SELECT (RDB$RELATION_ID) FROM RDB$DATABASE");
            // Firebird server: "SELECT X'4142' FROM RDB$DATABASE -> CONSTANT CHAR: [B@...", the value is a byte array with the bytes 0x41 0x42;
            // proxy: "SELECT X'4142' FROM RDB$DATABASE -> update count 0"
            execute(connection, "SELECT X'4142' FROM RDB$DATABASE");
            connection.setAutoCommit(false);
            // Firebird server and proxy: "INSERT INTO T_PLAIN (ID, NAME) VALUES (9501, 'before') -> update count 1"
            execute(connection, "INSERT INTO T_PLAIN (ID, NAME) VALUES (9501, 'before')");
            // Firebird server: "SELECT CASE WHEN 1 > 0 THEN 'a' ELSE 'b' END FROM RDB$DATABASE -> CASE CHAR(1): a";
