    static void updateLockedRow(final String name, final Connection connection, final TransactionParameterBuffer tpb) throws Exception {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        try (Connection holder = DriverManager.getConnection(SERVER_URL, SERVER_USER, SERVER_PASSWORD)) {
            holder.setAutoCommit(false);
            execute(holder, "UPDATE T_PLAIN SET NAME = 'holder' WHERE ID = 8953");
            connection.setAutoCommit(false);
            connection.unwrap(FirebirdConnection.class).setTransactionParameters(tpb);
            Future<String> update = executor.submit(() -> execute(connection, "UPDATE T_PLAIN SET NAME = 'second' WHERE ID = 8953"));
            try {
                System.out.println(name + ", update: " + update.get(5, TimeUnit.SECONDS));
                holder.rollback();
            } catch (final TimeoutException ex) {
                System.out.println(name + ", update: no answer within 5 seconds");
                // Releases the lock, so that the waiting update can go on
                holder.rollback();
                System.out.println(name + ", update after the other transaction rolled back: " + update.get(10, TimeUnit.SECONDS));
            }
            connection.rollback();
        } finally {
            executor.shutdownNow();
        }
    }

    static String execute(final Connection connection, final String sql) {
        try (Statement statement = connection.createStatement()) {
            statement.executeUpdate(sql);
            return "success";
        } catch (final SQLException ex) {
            return ex.getMessage();
        }
    }

    static void executeOnServer(final String sql) throws SQLException {
        try (Connection connection = DriverManager.getConnection(SERVER_URL, SERVER_USER, SERVER_PASSWORD)) {
            connection.createStatement().execute(sql);
        }
    }
}
