            // proxy: "SELECT FIRST (1 + 1) ID FROM T_PLAIN WHERE ID = -1 -> error: Dynamic SQL Error; You have an error in your SQL syntax: no viable alternative at input '+1)' [SQLState:42000, ISC error code:335544569]"
            execute(connection, "SELECT FIRST (1 + 1) ID FROM T_PLAIN WHERE ID = -1");
